@layer components {
  :where([data-control-family="accordion"][data-slot="root"]) {
    --accordion-item-border-color: var(--border);
    --accordion-trigger-foreground: var(--foreground);
    --accordion-trigger-hover-foreground: oklch(from var(--foreground) l c h / 0.8);
    --accordion-icon-foreground: var(--muted-foreground);
  }
  :where([data-control-family="accordion"][data-slot="item"]) {
    border-block-end: 1px solid var(--accordion-item-border-color);
  }

  :where([data-control-family="accordion"][data-slot="item"]:last-child) {
    border-block-end: 0;
  }

  :where([data-control-family="accordion"][data-slot="trigger"]) {
    color: var(--accordion-trigger-foreground);
    font-size: var(--text-body);
    outline: none;
    transition: color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="accordion"][data-slot="trigger"]:hover) {
    color: var(--accordion-trigger-hover-foreground);
  }

  :where([data-control-family="accordion"][data-slot="trigger"]:focus-visible) {
    box-shadow: 0 0 0 2px var(--focus-ring, oklch(from var(--foreground) l c h / 0.2));
  }

  :where([data-control-family="accordion"][data-slot="trigger"][data-disabled]) {
    cursor: not-allowed;
    opacity: 0.5;
  }

  :where([data-control-family="accordion"][data-slot="icon"]) {
    color: var(--accordion-icon-foreground);
    transition: rotate var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="accordion"][data-slot="trigger"][data-panel-open] > [data-slot="icon"]) {
    rotate: 180deg;
  }

  :where([data-control-family="accordion"][data-slot="panel"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
    height: var(--accordion-panel-height);
    overflow: hidden;
    transition: height var(--duration-base) var(--ease-emphasized);
  }

  :where(
    [data-control-family="accordion"][data-slot="panel"][data-starting-style],
    [data-control-family="accordion"][data-slot="panel"][data-ending-style]
  ) {
    height: 0;
  }

  :where([data-control-family="accordion"][data-slot="trigger"]) {
    --_accordion-trigger-text-align: left;
    text-align: var(--_accordion-trigger-text-align);
    font-weight: var(--font-weight-medium);
  }
}

@property --accordion-item-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --accordion-trigger-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --accordion-trigger-hover-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --accordion-icon-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { ChevronDown } from "lucide-react";
import type { AccordionItemProps, AccordionPanelProps, AccordionProps, AccordionTriggerProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

// Panel height animates from Base UI's --accordion-panel-height, with no JS measuring.
export function Accordion({ className, ...props }: AccordionProps) {
  return (
    <AccordionPrimitive.Root
      data-control-ui="accordion"
      data-control-family="accordion"
      data-slot="root"
      className={className}
      {...props}
    />
  );
}

export function AccordionItem({ className, ...props }: AccordionItemProps) {
  return (
    <AccordionPrimitive.Item
      data-control-ui="accordion"
      data-control-family="accordion"
      data-slot="item"
      className={className}
      {...props}
    />
  );
}

export function AccordionTrigger({ className, children, ...props }: AccordionTriggerProps) {
  return (
    <AccordionPrimitive.Header className="flex">
      <AccordionPrimitive.Trigger
        data-control-ui="accordion"
        data-control-family="accordion"
        data-slot="trigger"
        className={cn("group flex flex-1 cursor-pointer select-none items-center justify-between gap-4 py-3", className)}
        {...props}
      >
        {children}
        <ChevronDown
          aria-hidden="true"
          data-control-ui="accordion"
          data-control-family="accordion"
          data-slot="icon"
          className="size-4 shrink-0"
        />
      </AccordionPrimitive.Trigger>
    </AccordionPrimitive.Header>
  );
}

export function AccordionPanel({ className, children, ...props }: AccordionPanelProps) {
  return (
    <AccordionPrimitive.Panel data-control-ui="accordion" data-control-family="accordion" data-slot="panel" {...props}>
      <div className={cn("pb-3", className)}>{children}</div>
    </AccordionPrimitive.Panel>
  );
}
